<?php declare(strict_types=1);use FMonitor2\YiiRuntime\Assets\ShellAssetBundle;use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;ShellAssetBundle::register($this);$names=['busy'=>'Заняты','free'=>'Свободны','unknown'=>'Нет данных','releasing'=>'Освобождаются','conflict'=>'Конфликты'];$title=$names[$bucket];ViewSupport::begin($this,$title,$identity,'dashboard');?><main class="fm2-dashboard-page"><div class="fm2-page-header"><div><h1><?=Html::encode($title)?></h1><p><?=Html::encode((new DateTimeImmutable($weekStart))->format('d.m').'–'.(new DateTimeImmutable($weekEnd))->format('d.m'))?> · <?=$count?> из <?=$denominator?></p></div><a class="shlz-button shlz-button--secondary" href="/pilot/dashboard#installer-forecast">К дашборду</a></div><section class="fm2-list-surface"><ol><?php foreach($members as$m):?><li data-forecast-member><strong><?=Html::encode((string)$m['fio'])?></strong> · <?=Html::encode((string)$m['installerTabId'])?><?php foreach($m['reasons']as$r):?><p data-forecast-reason><?=Html::encode((string)$r['registrationNumber'])?> · <?=Html::encode((string)$r['startDate'])?>–<?=Html::encode((string)($r['endDate']??'без даты окончания'))?></p><?php endforeach?></li><?php endforeach?></ol></section></main><?php ViewSupport::end($this);
